import numpy as np
h=66.;w=10.;d=np.array([44.,39.,39.]);g=700.
def sim(m3=10,omega=2.5):
 m=np.array([1.,1.,m3,1.]);I=m*(h*h+w*w)/3
 b=np.arcsin((d[1]-w)/h);a=b+np.arcsin((d[0]*np.cos(b)-w)/h)
 q=np.array([a,b,0.,0.]);v=np.array([1.4,omega,0.,0.]);hist=[];dt=1/2400
 for k in range(6600):
  torque=m*g*(h*np.sin(q)-w*np.cos(q))/2
  v+=dt*(torque/I-.08*v);q+=dt*v
  for it in range(8):
   for i in range(4):
    if q[i]<0:
     q[i]=0;v[i]=max(0,v[i])
   for i in range(3):
    aa=q[i];bb=q[i+1]
    if aa>1.65:continue
    gap=d[i]*np.cos(bb)-w-h*np.sin(aa-bb)
    if gap<0:
     ja=-h*np.cos(aa-bb);jb=-d[i]*np.sin(bb)+h*np.cos(aa-bb)
     den=ja*ja/I[i]+jb*jb/I[i+1]
     dq=-gap/den;q[i]+=ja/I[i]*dq;q[i+1]+=jb/I[i+1]*dq
     vn=ja*v[i]+jb*v[i+1]
     if vn<0:
      imp=-1.03*vn/den;v[i]+=ja/I[i]*imp;v[i+1]+=jb/I[i+1]*imp
   for i in range(4):
    if q[i]>1.57:q[i]=1.57;v[i]=0
  if k%100==0:hist.append(q.copy())
 hist=np.array(hist)
 print('mass',m3,'v',omega,'max',hist.max(axis=0),'final',hist[-1])
 print('third angles',np.round(hist[:30,2],3))
 return hist
for om in [1.5,2,2.5,3]:sim(10,om)
sim(1,2.5)
